method.testScript:
const t = document.body.innerText;
return t.includes('Started Document Data Refresh Job')
	&& t.includes('Finished Document Data Refresh Job')
	&& ! t.includes('Document Data Refresh requested for');

method.execute:
const t = document.body.innerText;
const h = t.search(/\nconversations\nEvictions/);
const d = t.indexOf('\nDisk\n', h);
return /Entries:\s*(\d+)/.exec(t.substring(d))[1];

method.testScript:
const t = document.body.innerText;
const h = t.search(/\nconversations\nEvictions/);
const d = t.indexOf('\nDisk\n', h);
return Number(/Entries:\s*(\d+)/.exec(t.substring(d))[1]) < Number(sail.vars.conversationsBefore);
